//! Phase B (Issue 4) golden-fixture harness: the exact GEV monotonicity repro.
//!
//! Loads `tests/golden/gev_monotone_golden.json` (generated by
//! `tools/generate_gev_monotone_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and checks the Rust GEV CP path
//! ([`fitdistcp_core::api::predict_gev`]) against the reference on the literal
//! repro dataset from the Phase-1 numerical-issues report.
//!
//! # What this test proves
//!
//! Before Phase A the GEV CP quantiles at this small `n` (`n = 12`) could be
//! non-monotone in `p` (a decreasing tail) and the median could be negative.
//! The monotonicity guard
//! ([`fitdistcp_core::models::numerical::enforce_monotone_quantiles_for_p`])
//! now restores the non-decreasing invariant, and the `cp_monotone_clamped`
//! flag records whether it fired.
//!
//! The harness asserts:
//!
//! 1. **No NaN.** The fitted parameters and CP quantiles are finite.
//! 2. **Reference match.** The Rust `ml_params` match the reference at the
//!    optimizer tolerance (§3.2), and the CP quantiles match the reference at
//!    the §3.7 tolerance.
//! 3. **Monotone + non-negative median.** The returned CP quantiles are
//!    non-decreasing in `p` and the median (`p = 0.5`) is non-negative — the
//!    Phase A acceptance criteria.
//!
//! # Tolerance policy
//!
//! The canonical policy lives in [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md)
//! §7. The monotonicity guard is a deliberate Rust-only divergence from the
//! reference (which does not sort); see §7.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::api::{predict_gev, PredictionRequest};
use fitdistcp_core::models::GenExtreme;

/// GEV CP tolerance. The CP quantiles come from the DMGS expansion evaluated at
/// the optimizer's `ml_params`; the residual is dominated by the optimizer's
/// parameter agreement (the DMGS expansion itself is analytic). The observed
/// max residual is ~3.3e-6, so we use a documented `1e-5` (see
/// `tests/golden/TOLERANCE.md` §7).
const GEV_RTOL: f64 = 1e-5;
const GEV_ATOL: f64 = 1e-8;

/// Optimizer-produced parameter tolerance (§3.2).
const OPT_RTOL: f64 = 1e-4;
const OPT_ATOL: f64 = 1e-6;

/// The reference `fdalpha` default for the quantile-derived density.
const FDALPHA: f64 = 0.01;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "gev_monotone_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

fn make_request(y: Vec<f64>, p: Vec<f64>) -> PredictionRequest {
    PredictionRequest {
        y,
        x: vec![],
        p,
        t: None,
        t0: None,
        n0: None,
        means: None,
    }
}

/// The exact repro must return a non-negative median and non-decreasing CP
/// quantiles, and match the reference (Issue 4, Phase B).
#[test]
fn golden_gev_monotone_repro() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get("repro_x").as_f64_vec();
    let m = models.get("repro_gev");
    let ref_params = m.get("params").as_f64_vec();

    let req = make_request(y.clone(), p_grid.clone());
    let fit = predict_gev(GenExtreme, &req, &[1.0, 1.0, 0.0], FDALPHA);

    // (1) No NaN.
    assert!(
        fit.ml_params.iter().all(|v| v.is_finite()),
        "repro_gev: ml_params not finite: {:?}",
        fit.ml_params
    );
    assert!(
        fit.cp_quantiles.iter().all(|v| v.is_finite()),
        "repro_gev: cp_quantiles not finite: {:?}",
        fit.cp_quantiles
    );

    // (2) The fitted parameters match the reference (optimizer tolerance).
    compare_vec(
        &fit.ml_params,
        &ref_params,
        OPT_RTOL,
        OPT_ATOL,
        "repro_gev.ml_params",
    );

    // (3) The CP quantiles match the reference at the §3.7 tolerance.
    compare_vec(
        &fit.cp_quantiles,
        &m.get("cp_quantiles").as_f64_vec(),
        GEV_RTOL,
        GEV_ATOL,
        "repro_gev.cp_quantiles",
    );

    // (4) Phase A acceptance: non-decreasing in `p`, non-negative median.
    assert!(
        fit.cp_quantiles.windows(2).all(|w| w[0] <= w[1]),
        "CP quantiles must be non-decreasing in p, got {:?}",
        fit.cp_quantiles
    );
    assert!(
        fit.cp_quantiles[0] >= 0.0,
        "CP median must be non-negative, got {}",
        fit.cp_quantiles[0]
    );

    eprintln!(
        "repro_gev: params = {:?}, cp_quantiles = {:?}, clamped = {}",
        fit.ml_params, fit.cp_quantiles, fit.cp_monotone_clamped
    );
}
